func (s *Service) reconstructSaveBroadcastDataColumnSidecars(ctx, slot, proposerIndex, root) error {
	// Load verified sidecars (already passed gossip validation)
	verifiedSidecars, _ = s.cfg.dataColumnStorage.Get(root, nil)
	// Reconstruct via Reed-Solomon from verified inputs
	reconstructedSidecars, _ = peerdas.ReconstructDataColumnSidecars(verifiedSidecars)
	// Save ONLY custody columns - bypasses receiveDataColumnSidecar (and thus setSeenDataColumnIndex)
	s.cfg.dataColumnStorage.Save(toSaveSidecars)
	// Note: 'We do not call receiveDataColumn, because it will ignore incoming data columns
	//        via gossip while we did not broadcast (yet) the reconstructed data columns.'
	// Schedule broadcast - bypasses validateDataColumn:
	// Skips: ValidFields, CorrectSubnet, NotFromFutureSlot, SidecarParentSeen, SidecarParentValid,
	//        ValidProposerSignature, SidecarParentSlotLower, SidecarDescendsFromFinalized,
	//        SidecarInclusionProven, SidecarKzgProofVerified, SidecarProposerExpected
	s.scheduleMissingDataColumnSidecarsBroadcast(ctx, root, proposerIndex, slot)
}
